CREATE TEMPORARY VIEW search_be_log AS
SELECT
    GET_JSON_OBJECT(value, '$.request.header.request_id') AS request_id
    ,FROM_JSON(GET_JSON_OBJECT(value, '$.response.realtime_reward_info.realtime_reward_item_ids'), 'ARRAY<BIGINT>')  AS realtime_reward_item_ids
    ,FROM_JSON(GET_JSON_OBJECT(value, '$.response.realtime_reward_info.unexposed_item_ids'), 'ARRAY<BIGINT>') AS unexposed_item_ids
    ,GET_JSON_OBJECT(`value`,'$.response.device_label') AS device_label
    ,GET_JSON_OBJECT(value,'$.response.other_info.query_translation') AS query_translation
    ,dt
    ,hh
    ,UPPER(GET_JSON_OBJECT(`value`,'$.request.header.country')) AS grass_region
FROM
    search_data.ods_search_intel_log_v2_1h_raw
WHERE
    dt = ${regional_date}
    AND hh = ${regional_hour}
    AND UPPER(GET_JSON_OBJECT(`value`,'$.request.header.country')) IN ('TW','CL','MX','MY','CO','BR','SG','TH','PH','VN','ID','AR'); -- 'KH','MM','LA'

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_be_log_filtered AS
SELECT
    request_id
    ,realtime_reward_item_ids
    ,unexposed_item_ids
    ,device_label
    ,query_translation
    ,grass_region
    ,DATE(date_timezone_convert(dt,hh,'SG',grass_region,"yyyy-MM-dd")) AS local_date
    ,CAST(date_timezone_convert(dt,hh,'SG',grass_region,"HH") AS INT) AS local_hour
    ,CAST(dt AS DATE) AS regional_date
    ,CAST(hh AS INT) AS regional_hour
FROM
    search_be_log;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_be_log_ranked AS
SELECT
    request_id
    ,realtime_reward_item_ids
    ,unexposed_item_ids
    ,device_label
    ,query_translation
    ,grass_region
    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,ROW_NUMBER() OVER (PARTITION BY grass_region, local_date, request_id ORDER BY grass_region) AS rn
FROM
    search_be_log_filtered;

